package types

import (
	"sort"
	"strings"
	"testing"
)

func TestDatabaseServerDisplayOrder(t *testing.T) {
	first := NewDatabaseServerV3("alpha", nil, DatabaseServerSpecV3{HostID: "host-b"})
	second := NewDatabaseServerV3("beta", nil, DatabaseServerSpecV3{HostID: "host-c"})
	third := NewDatabaseServerV3("alpha", nil, DatabaseServerSpecV3{HostID: "host-a"})
	servers := []DatabaseServer{first, second, third}

	unique := DeduplicateDatabaseServers(servers)
	if len(unique) != 2 || unique[0] != first || unique[1] != second {
		t.Fatalf("deduplication did not preserve first occurrences: %v", unique)
	}
	if !strings.Contains(first.String(), "HostID=host-b") {
		t.Fatalf("server string does not contain host ID: %s", first)
	}

	sort.Sort(SortedDatabaseServers(servers))
	if servers[0] != third || servers[1] != first || servers[2] != second {
		t.Fatalf("unexpected name/host ordering: %v", servers)
	}
}

